		source: "import { createPersistentStateDefinition, isPersistentStateDefinition, PERSISTENT_STATE_VERSION_MAX, registerPersistentStateDefinition, } from \"rowcat:internal/persistent-state\";\nimport { isSerializable, } from \"rowcat:internal/serializable\";\nimport { createStoryStateDefinition, isStoryStateDefinition, registerStoryStateDefinition, STORY_STATE_VERSION_MAX, } from \"rowcat:internal/story-state\";\nexport { isPersistentStateDefinition, isSerializable, isStoryStateDefinition, PERSISTENT_STATE_VERSION_MAX, STORY_STATE_VERSION_MAX, };\nexport function defineStoryState(definition) {\n    const created = createStoryStateDefinition(definition);\n    registerStoryStateDefinition(created);\n    return created;\n}\nexport function definePersistentState(definition) {\n    const created = createPersistentStateDefinition(definition);\n    registerPersistentStateDefinition(created);\n    return created;\n}\n",
